//! Loads the fixture dump (`tests/fixtures/tables`, generated by `tests/fixtures/make_fixtures.py`
//! from build 1.60.1.70009) and checks the joins the exporters rely on. The expected values are
//! the ones quoted in `data/SPELL_INSTRUCTIONS.md` §1.8, `data/TALENT_INSTRUCTIONS.md` §1.7 and
//! `data/ITEM_INSTRUCTIONS.md` §1.4–1.9.

use std::path::{Path, PathBuf};

use csim_tables::tables::{ALL_TABLES, ItemDamageTable, SpellEffectRow, SpellNameRow};
use csim_tables::{TableDir, TableError, Tables};

const BUILD: &str = "1.60.1.70009";

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/tables")
}

fn tables() -> Tables {
    Tables::load_dir(fixtures()).expect("fixture tables load")
}

/// A scratch directory under the target dir, removed when dropped.
struct Scratch(PathBuf);

impl Scratch {
    fn new(name: &str) -> Self {
        let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join(name);
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }

    fn write(&self, file: &str, content: &str) {
        std::fs::write(self.0.join(file), content).unwrap();
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[test]
fn directory_detects_the_build_and_lists_every_table() {
    let dir = TableDir::open(fixtures()).unwrap();
    assert_eq!(dir.build(), BUILD);
    assert_eq!(
        TableDir::builds(fixtures()).unwrap(),
        vec![BUILD.to_owned()]
    );
    let names: Vec<&str> = dir.table_names().collect();
    assert_eq!(names.len(), ALL_TABLES.len());
    for table in ALL_TABLES {
        assert!(dir.has(table), "{table} missing from fixtures");
        assert!(
            dir.path(table)
                .unwrap()
                .ends_with(format!("{table}.{BUILD}.csv"))
        );
    }
    assert!(csim_tables::dir::missing_tables(&dir, ALL_TABLES.iter().copied()).is_empty());
    assert_eq!(dir.row_count("SpellShapeshiftForm").unwrap(), 3);
    assert_eq!(dir.columns("SpellName").unwrap(), ["ID", "Name_lang"]);
    assert!(matches!(
        dir.path("ItemExtendedCost"),
        Err(TableError::MissingTable { ref table, .. }) if table == "ItemExtendedCost"
    ));
}

#[test]
fn open_build_selects_a_build_and_rejects_unknown_ones() {
    let dir = TableDir::open_build(fixtures(), BUILD).unwrap();
    assert_eq!(dir.build(), BUILD);
    assert!(matches!(
        TableDir::open_build(fixtures(), "2.0.0.1"),
        Err(TableError::UnknownBuild { ref build, .. }) if build == "2.0.0.1"
    ));
}

#[test]
fn directory_errors_are_specific() {
    let missing = fixtures().join("does-not-exist");
    assert!(matches!(
        TableDir::open(&missing),
        Err(TableError::Io { ref dir, .. }) if *dir == missing
    ));

    let empty = Scratch::new("csim-tables-empty");
    empty.write("README.txt", "not a table");
    assert!(matches!(
        TableDir::open(&empty.0),
        Err(TableError::NoTables { .. })
    ));

    let two = Scratch::new("csim-tables-two-builds");
    two.write("SpellName.1.0.0.1.csv", "ID,Name_lang\n1,A\n");
    two.write("SpellName.1.0.0.2.csv", "ID,Name_lang\n1,B\n");
    assert!(matches!(
        TableDir::open(&two.0),
        Err(TableError::AmbiguousBuild { ref builds, .. })
            if builds == &["1.0.0.1".to_owned(), "1.0.0.2".to_owned()]
    ));
    let dir = TableDir::open_build(&two.0, "1.0.0.2").unwrap();
    let rows = dir.read::<SpellNameRow>().unwrap();
    assert_eq!(rows[0].name, "B");
    assert!(matches!(
        dir.read::<SpellEffectRow>(),
        Err(TableError::MissingTable { ref table, ref build, .. })
            if table == "SpellEffect" && build == "1.0.0.2"
    ));
}

#[test]
fn malformed_files_are_reported_with_context() {
    let bad = Scratch::new("csim-tables-bad");
    bad.write("SpellName.1.0.0.1.csv", "ID,Title\n1,A\n");
    bad.write(
        "SpellDuration.1.0.0.1.csv",
        "ID,Duration,MaxDuration,DurationPerResource\n1,ten,0,0\n",
    );
    bad.write(
        "SpellCastTimes.1.0.0.1.csv",
        "ID,Base,Minimum\n1,0,0\n2,0\n",
    );
    let dir = TableDir::open(&bad.0).unwrap();
    assert!(matches!(
        dir.read::<SpellNameRow>(),
        Err(TableError::MissingColumn { ref table, ref column }) if table == "SpellName" && column == "Name_lang"
    ));
    let err = dir
        .read::<csim_tables::tables::SpellDurationRow>()
        .unwrap_err();
    assert_eq!(
        err.to_string(),
        "SpellDuration line 2, column Duration: cannot parse \"ten\" as i32"
    );
    assert!(matches!(
        dir.read::<csim_tables::tables::SpellCastTimesRow>(),
        Err(TableError::Csv { .. })
    ));
}

#[test]
fn streaming_rows_reads_records_by_header_name() {
    let dir = TableDir::open(fixtures()).unwrap();
    let mut names = Vec::new();
    dir.for_each_row("SpellName", |row| {
        if row.field::<u32>("ID")? == 12294 {
            names.push(row.field::<String>("Name_lang")?);
        }
        Ok(())
    })
    .unwrap();
    assert_eq!(names, ["Mortal Strike"]);
    let kept = dir
        .read_where::<SpellNameRow>(|r| r.name.starts_with("Deep"))
        .unwrap();
    assert_eq!(kept.len(), 3, "Deep Wounds x2 and Deep Wound");
}

#[test]
fn mortal_strike_joins_every_spell_table() {
    let t = tables();
    assert_eq!(t.build(), BUILD);
    let id = 12294;
    assert!(t.spell_exists(id));
    assert!(!t.spell_exists(1));
    assert_eq!(t.spell_name(id), Some("Mortal Strike"));
    assert_eq!(t.spell(id).unwrap().name_subtext, "Rank 1");

    let misc = t.spell_misc(id).unwrap();
    assert_eq!(misc.attributes[0], 0x50010);
    assert_eq!(misc.school_mask, 1);
    assert_eq!(
        t.spell_duration(misc.duration_index).unwrap().duration,
        10_000
    );
    assert_eq!(t.spell_cast_times(misc.casting_time_index).unwrap().base, 0);
    assert_eq!(t.spell_range(misc.range_index).unwrap().range_max[0], 5.0);

    let effects = t.spell_effects(id);
    assert_eq!(effects.len(), 2);
    assert_eq!(
        (
            effects[0].effect_index,
            effects[0].effect,
            effects[0].effect_aura
        ),
        (0, 6, 118)
    );
    assert_eq!(effects[0].effect_base_points, -50.0);
    assert_eq!(effects[0].effect_misc_value, [127, 0]);
    assert_eq!(effects[0].implicit_target, [6, 0]);
    assert_eq!((effects[1].effect_index, effects[1].effect), (1, 121));
    assert_eq!(effects[1].effect_base_points, 85.0);

    let power = t.spell_power(id);
    assert_eq!(power.len(), 1);
    assert_eq!((power[0].power_type, power[0].mana_cost), (1, 300));
    assert_eq!(t.power_type(1).unwrap().display_modifier, 10);
    assert_eq!(t.power_type(1).unwrap().max_base_power, 1000);

    let cd = t.spell_cooldowns(id).unwrap();
    assert_eq!(
        (
            cd.recovery_time,
            cd.category_recovery_time,
            cd.start_recovery_time
        ),
        (0, 6000, 1500)
    );
    let cat = t.spell_categories(id).unwrap();
    assert_eq!(
        (cat.category, cat.defense_type, cat.start_recovery_category),
        (971, 2, 133)
    );
    assert_eq!(t.spell_category(971).unwrap().name, "Mortal Strike");
    assert_eq!(t.spell_category(133).unwrap().name, "Global");

    let levels = t.spell_levels(id).unwrap();
    assert_eq!(
        (levels.base_level, levels.spell_level, levels.max_level),
        (40, 40, 0)
    );
    let class = t.spell_class_options(id).unwrap();
    assert_eq!(class.spell_class_set, 4);
    assert_eq!(class.spell_class_mask, [33554432, 0, 0, 0]);
    let equip = t.spell_equipped_items(id).unwrap();
    assert_eq!(
        (equip.equipped_item_class, equip.equipped_item_subclass),
        (2, 173555)
    );
    assert!(t.spell_shapeshift(id).is_none());
    assert!(t.spell_aura_options(id).is_none());
    assert!(t.spell_labels(id).contains(&25));

    let abilities: Vec<_> = t.skill_line_abilities_of_spell(id).collect();
    assert_eq!(abilities.len(), 1);
    assert_eq!((abilities[0].skill_line, abilities[0].class_mask), (26, 1));
}

